// Pseudo sketch: per-task energy accounting
struct core_state { long long quota; atomic_ll energy_acc; pthread_mutex_t lock; };
void on_dispatch(Task *t){
  long long d = estimate_energy(t); // from PMU
  atomic_add(&t->energy, d);
  if (atomic_read(&t->energy) > t->quota) throttle(t);
}
``` 

